#!/bin/sh
# Prints Formula/andysu.rb for a release: prebuilt static CLI binaries from the GitHub Release.
#   scripts/homebrew-formula.sh <version> <dir with andysu-<target> binaries>
set -eu
v="$1"
d="$2"
url="https://github.com/dixonSolutions/AndySU/releases/download/v$v"
sha() { sha256sum "$d/andysu-$1" | cut -d' ' -f1; }
cat <<RUBY
# Generated by scripts/homebrew-formula.sh for each release. Install:
#   brew tap dixonsolutions/andysu https://github.com/dixonSolutions/AndySU
#   brew install dixonsolutions/andysu/andysu
class Andysu < Formula
  desc "Complete, permission-free self-updates for apps outside the stores"
  homepage "https://github.com/dixonSolutions/AndySU"
  version "$v"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$url/andysu-aarch64-apple-darwin"
      sha256 "$(sha aarch64-apple-darwin)"
    end
    on_intel do
      url "$url/andysu-x86_64-apple-darwin"
      sha256 "$(sha x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_arm do
      url "$url/andysu-aarch64-unknown-linux-musl"
      sha256 "$(sha aarch64-unknown-linux-musl)"
    end
    on_intel do
      url "$url/andysu-x86_64-unknown-linux-musl"
      sha256 "$(sha x86_64-unknown-linux-musl)"
    end
  end

  def install
    bin.install Dir["andysu-*"].first => "andysu"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/andysu --version")
  end
end
RUBY
